import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterLink, Router } from '@angular/router';
import { AuthService } from '../../core/auth.service';

declare const document: any;
declare const sessionStorage: any;

interface Plan { id: number; name: string; price: number; duration_months: number; classes_per_month: number | null; }

@Component({
  selector: 'app-select-plan',
  standalone: true,
  imports: [CommonModule, RouterLink],
  templateUrl: './plan.component.html',
  styleUrl: './plan.component.css'
})
export class PlanComponent implements OnInit {
  plans: Plan[] = [];
  selected: number | null = null;
  error = '';
  loading = true;
  private category = '';

  constructor(private auth: AuthService, private router: Router) {}

  async ngOnInit(): Promise<void> {
    this.category = sessionStorage.getItem('signup_category') || '';
    if (!this.category) {
      this.router.navigate(['/select-category']);
      return;
    }
    try {
      this.plans = await this.auth.getPlans(); // GET /api/auth/plans
    } catch {
      this.error = 'Could not load plans, please try again';
    } finally {
      this.loading = false;
    }
  }

  select(id: number): void {
    this.selected = id;
    this.error = '';
  }

  async confirm(): Promise<void> {
    if (!this.selected) {
      this.error = 'Please select a plan';
      return;
    }
    const btn = document.getElementById('plan-continue');
    btn?.classList.add('auth-form__submit--loading');
    btn.disabled = true;

    try {
      await this.auth.setSubscription(this.category, this.selected); // POST /api/auth/subscription
      sessionStorage.removeItem('signup_category');
      this.router.navigate(['/pending']);
    } catch (err: any) {
      this.error = err?.error?.error || 'Something went wrong, please try again';
    } finally {
      btn?.classList.remove('auth-form__submit--loading');
      btn.disabled = false;
    }
  }
}
